#!/bin/sh
# userspace-rcu 0.15.6 Installation Script for HongMeng Platform
# Generated by openharmony-compile-agent

set -e

PREFIX="${PREFIX:-/storage/Users/currentUser/usr/local}"
PACKAGE_NAME="userspace-rcu"
PACKAGE_VERSION="0.15.6"

echo "Installing ${PACKAGE_NAME}-${PACKAGE_VERSION} to ${PREFIX}"

# Check if package archive exists
if [ ! -f "${PACKAGE_NAME}-${PACKAGE_VERSION}-ohos-aarch64.tar.gz" ]; then
    echo "ERROR: Package archive not found: ${PACKAGE_NAME}-${PACKAGE_VERSION}-ohos-aarch64.tar.gz"
    exit 1
fi

# Create directories
mkdir -p "${PREFIX}/lib"
mkdir -p "${PREFIX}/include/urcu"
mkdir -p "${PREFIX}/lib/pkgconfig"
mkdir -p "${PREFIX}/share/doc/${PACKAGE_NAME}"

# Extract and install
echo "Extracting package..."
tar xzf "${PACKAGE_NAME}-${PACKAGE_VERSION}-ohos-aarch64.tar.gz"

echo "Installing libraries..."
cp -a lib/*.so* "${PREFIX}/lib/" 2>/dev/null || true
cp -a lib/*.a "${PREFIX}/lib/" 2>/dev/null || true

echo "Installing headers..."
cp -a include/urcu/*.h "${PREFIX}/include/urcu/"

echo "Installing pkg-config files..."
cp -a lib/pkgconfig/*.pc "${PREFIX}/lib/pkgconfig/" 2>/dev/null || true

echo "Installing documentation..."
cp -a share/doc/${PACKAGE_NAME}/* "${PREFIX}/share/doc/${PACKAGE_NAME}/" 2>/dev/null || true

# Update library cache (if available)
if command -v ldconfig >/dev/null 2>&1; then
    ldconfig -n "${PREFIX}/lib"
fi

echo "Installation complete!"
echo ""
echo "Installed to: ${PREFIX}"
echo "Libraries: ${PREFIX}/lib/liburcu*.so*"
echo "Headers: ${PREFIX}/include/urcu/"
echo ""
echo "To use in your project:"
echo "  export LD_LIBRARY_PATH=${PREFIX}/lib:\$LD_LIBRARY_PATH"
echo "  export PKG_CONFIG_PATH=${PREFIX}/lib/pkgconfig:\$PKG_CONFIG_PATH"
echo "  pkg-config --cflags --libs liburcu"